<script setup lang="ts">
import type { PointDraft, PointProperty, PropertyType } from '@/api/tracking'
defineProps<{ modelValue: PointDraft }>(); const emit=defineEmits<{ 'update:modelValue':[PointDraft] }>()
function add(m:PointDraft){emit('update:modelValue',{...m,properties:[...m.properties,{code:'',name:'',type:'STRING',required:false,sort_order:m.properties.length}]})}
function update(m:PointDraft,i:number,v:Partial<PointProperty>){const p=m.properties.slice();p[i]={...p[i]!,...v};emit('update:modelValue',{...m,properties:p})}
function remove(m:PointDraft,i:number){emit('update:modelValue',{...m,properties:m.properties.filter((_,x)=>x!==i)})}
</script>
<template><section><div class="section-heading"><h2>属性 Schema</h2><button type="button" class="secondary-button" @click="add(modelValue)">新增属性</button></div><div v-if="!modelValue.properties.length" class="empty-state">暂无自定义属性</div><div v-for="(p,i) in modelValue.properties" :key="i" class="property-row"><input :value="p.code" placeholder="属性编码" @input="update(modelValue,i,{code:($event.target as HTMLInputElement).value})"><input :value="p.name" placeholder="中文名称" @input="update(modelValue,i,{name:($event.target as HTMLInputElement).value})"><select :value="p.type" @change="update(modelValue,i,{type:($event.target as HTMLSelectElement).value as PropertyType})"><option v-for="t in ['STRING','INTEGER','DECIMAL','BOOLEAN','DATETIME','ENUM','ARRAY']" :key="t">{{ t }}</option></select><label><input type="checkbox" :checked="p.required" @change="update(modelValue,i,{required:($event.target as HTMLInputElement).checked})">必填</label><input v-if="p.type==='ENUM'" :value="p.enum_values?.join(',')" placeholder="枚举值，逗号分隔" @input="update(modelValue,i,{enum_values:($event.target as HTMLInputElement).value.split(',').map(v=>v.trim()).filter(Boolean)})"><select v-if="p.type==='ARRAY'" :value="p.array_item_type" @change="update(modelValue,i,{array_item_type:($event.target as HTMLSelectElement).value as PointProperty['array_item_type']})"><option value="">元素类型</option><option v-for="t in ['STRING','INTEGER','DECIMAL','BOOLEAN','DATETIME']" :key="t">{{ t }}</option></select><button type="button" class="danger-link" @click="remove(modelValue,i)">删除</button></div></section></template>
